import Foundation

/// What a small model is asked to name a conversation, and what of its answer
/// is kept (`TitleNamer`). Pure, so it can be tested without a model.
///
/// The owner, 2026-09-25: the list showed the first line of each thread cut
/// at 48 characters ("I want to create a— I want to create a plan…"), and
/// asked for names "auto-generated by the AI … as cheap as possible … very
/// minimal". Only your first message goes in: Moe's own turns and the brief
/// it sends with each one are what made Hermes's titles read "ready #45".
public enum TitleRules {

    public static let system = """
        You name conversations for a chat list. Reply with the name only: 2 to 5 \
        words saying what the person wants, like "Book table at Nopa" or \
        "Pricing for the launch". No quotes, no emoji, no full stop, never a \
        sentence, never "Conversation about".
        """

    /// Your first words, one paragraph, at most 300 characters: all a name
    /// needs, and the whole cost of the call.
    public static func user(firstMessage: String) -> String {
        let text = firstMessage.trimmingCharacters(in: .whitespacesAndNewlines)
        let clipped = text.count > 300 ? String(text.prefix(300)) : text
        return "Name this conversation. It starts:\n\n" + clipped
    }

    /// The model's reply as a title, or nil when it is not one.
    public static func accept(_ reply: String) -> String? {
        var s = reply.trimmingCharacters(in: .whitespacesAndNewlines)
        if let nl = s.firstIndex(of: "\n") { s = String(s[..<nl]) }
        s = s.replacingOccurrences(of: "**", with: "").replacingOccurrences(of: "__", with: "")
        for label in ["Title:", "Name:", "title:", "name:"] where s.hasPrefix(label) {
            s = String(s.dropFirst(label.count))
        }
        s = s.trimmingCharacters(in: .whitespaces)
        let wrappers: Set<Character> = ["\"", "'", "“", "”", "‘", "’", "*", "`", "#"]
        while let f = s.first, wrappers.contains(f) { s.removeFirst() }
        while let l = s.last, wrappers.contains(l) || l == "." { s.removeLast() }
        let words = s.split(separator: " ")
        guard !s.isEmpty, words.count <= 8, s.count <= 48 else { return nil }
        return s
    }

    /// Only threads you started, and only once there is an answer to name.
    public static func wants(hasTitle: Bool, firstMessage: String?, answered: Bool) -> Bool {
        guard !hasTitle, answered, let m = firstMessage else { return false }
        return m.trimmingCharacters(in: .whitespacesAndNewlines).count >= 2
    }
}
